css:
.notifications-container {
  width: 320px;
  height: auto;
  font-size: 0.875rem;
  line-height: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.flex {
  display: flex;
}

.flex-shrink-0 {
  flex-shrink: 0;
}

.dad-joke {
  padding: 1rem;
  border-radius: 0.375rem;
  background-color: rgb(248, 231, 28);
}

.dad-joke-svg {
  color: rgb(255, 255, 255);
  width: 1.25rem;
  height: 1.25rem;
}

.dad-joke-prompt-wrap {
  margin-left: 0.75rem;
}

.dad-joke-prompt-heading {
  font-weight: bold;
  color: rgb(57, 55, 54);
}

.dad-joke-prompt {
  margin-top: 0.5rem;
  color: rgb(57, 55, 54);
}

.dad-joke-button-container {
  display: flex;
  margin-top: 0.875rem;
  margin-bottom: -0.375rem;
  margin-left: -0.5rem;
  margin-right: -0.5rem;
}

.dad-joke-button-main {
  padding-top: 0.375rem;
  padding-bottom: 0.375rem;
  padding-left: 0.5rem;
  padding-right: 0.5rem;
  background-color: #F75404;
  color: #FFFFFF;
  font-size: 0.875rem;
  line-height: 1.25rem;
  font-weight: bold;
  border-radius: 0.375rem;
  border: none
}

.dad-joke-button-main:hover {
  background-color: #D1410C;
}
